def sum_common_divisors(a, b):
    def get_divisors(n):
        divs = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
        return sorted(divs)

    divs_a = get_divisors(a)
    divs_b = get_divisors(b)

    common = set(divs_a).intersection(set(divs_b))
